<script setup>
import { dateTime } from './model.js'
defineProps({ audit:Object, acquisition:Object, status:String, inherited:Boolean })
const names = {sh_main:'上交所主板',sh_star:'上交所科创板',sh_retired:'上交所终止上市',sz_active:'深交所A股',sz_retired:'深交所终止上市'}
const reasons = {only_official_observation:'仅官方回溯观察',official_lifecycle_unavailable:'官方生命周期缺失',outside_official_interval:'不在官方日期区间',ambiguous_lifecycle:'多重生命周期待核实'}
const states = {RUNNING:'采集中',COMPLETED:'采集核对完成',FAILED:'采集失败',CANCELLED:'已停止',INTERRUPTED:'已中断'}
</script>
<template><section v-if="audit" class="panel rep-section" aria-label="免费交易所档案核对结果">
  <h2>沪深交易所生命周期核对 <span class="tag tag-warn">PARTIAL · 回溯观察</span></h2>
  <p class="condition-note"><template v-if="inherited">沿用父版本核对 · {{ audit.sources.length }} 份官方响应。</template><template v-else>{{ states[status] || status }} · 已请求 {{ acquisition?.calls_started ?? 0 }} 次，冻结 {{ audit.sources.length }} / 5 份官方响应。</template>比较区间 {{ audit.start }} ~ {{ audit.end }}；没有执行条件筛选。</p>
  <p v-if="!inherited && acquisition?.error" class="error-text" role="alert">采集未完成：{{ acquisition.error }}。成功来源已保留，缺失来源不按空名单处理。</p>
  <div class="report-table-scroll"><table class="data"><thead><tr><th>信号日</th><th>父名单</th><th>官方回溯</th><th>共同成员</th><th>仅父名单</th><th>仅官方观察</th></tr></thead><tbody><tr v-for="annual in audit.annual" :key="annual.signal_day"><td>{{ annual.signal_day }}</td><td>{{ annual.native_count }}</td><td>{{ annual.official_observed_count ?? '待完成' }}</td><td>{{ annual.common_count }}</td><td>{{ annual.only_native_count ?? '待完成' }}</td><td>{{ annual.only_official_count }}</td></tr></tbody></table></div>
  <p class="condition-note">上市／摘牌日期对比：MATCH {{ audit.check_counts.MATCH }} / CONFLICT {{ audit.check_counts.CONFLICT }} / METHOD_DIFFERENCE {{ audit.check_counts.METHOD_DIFFERENCE }} / UNAVAILABLE {{ audit.check_counts.UNAVAILABLE }}。MATCH只代表该项日期一致，不证明历史名单或修订档案完整。</p>
  <details v-for="annual in audit.annual" :key="annual.signal_day" class="bt-source-details"><summary>{{ annual.signal_day }} 名单差异（{{ annual.details.length }}）</summary><div class="report-table-scroll"><table class="data"><thead><tr><th>代码</th><th>当前简称</th><th>状态</th><th>说明</th></tr></thead><tbody><tr v-for="row in annual.details" :key="row.code"><td>{{ row.code }}</td><td>{{ row.name }}</td><td>{{ row.status }}</td><td>{{ reasons[row.reason] || row.reason }}</td></tr><tr v-if="!annual.details.length"><td colspan="4">本次名单观察无集合差异，仍须历史完整性审核。</td></tr></tbody></table></div></details>
  <details class="bt-source-details"><summary>查看生命周期日期核对（{{ audit.checks.length }}）</summary><div class="report-table-scroll"><table class="data"><thead><tr><th>代码</th><th>父上市日</th><th>父摘牌日</th><th>官方区间</th><th>状态</th></tr></thead><tbody><tr v-for="row in audit.checks" :key="row.code"><td>{{ row.code }}</td><td>{{ row.native_listed_at || '—' }}</td><td>{{ row.native_delisted_at || '—' }}</td><td><div v-for="(interval,index) in row.official_intervals" :key="index">{{ interval.listed_at }} ~ {{ interval.delisted_at || '未摘牌' }}</div><span v-if="!row.official_intervals.length">缺少</span></td><td>{{ row.status }}</td></tr></tbody></table></div></details>
  <details class="bt-source-details"><summary>查看免费官方原文与哈希（{{ audit.sources.length }}）</summary><div v-for="source in audit.sources" :key="source.packet_sha256" class="bt-check-item"><div>{{ names[source.query.table] }} · A股 {{ source.row_count }} 条 · 排除B股等 {{ source.excluded_non_a_share }} 条</div><p>抓取 {{ dateTime(source.retrieved_at) }} · {{ source.source_url }}</p><p class="num">原文 SHA256：{{ source.document_sha256 }}<br />响应 SHA256：{{ source.packet_sha256 }}</p><pre>{{ JSON.stringify(source.params,null,2) }}</pre></div></details>
  <ul class="bt-limitations"><li v-for="gap in audit.gaps" :key="gap">{{ gap }}</li></ul>
</section></template>
